    """TC_AUTH_015: Create account fails with invalid email format

    Scenario: SC_AUTH_005
    Expected: Validation error appears for invalid email format and account is not created.
    Note: No explicit error-message element was discovered for the invalid email format. The script asserts that the Create account button remains visible (i.e. the form was not submitted) as a conservative proxy for the expected validation failure.
    """
    with app.step('Open the landing page', action='goto', element=''):
        app.goto('/~/+/')
    with app.step("Click 'Create account' button on landing page", action='click', element='landing.create_account_button'):
        app.pages.landing.create_account_button.click()
    with app.step('Enter display name', action='fill', element='create_account.display_name_textbox'):
        app.pages.create_account.display_name_textbox.fill('Test User')
    with app.step('Enter invalid email format', action='fill', element='create_account.email_textbox'):
        app.pages.create_account.email_textbox.fill('invalid-email-format')
    with app.step('Enter password', action='fill', element='create_account.password_textbox'):
        app.pages.create_account.password_textbox.fill('ValidPass123!')
    with app.step('Enter matching password in confirm password field', action='fill', element='create_account.confirm_password_textbox'):
        app.pages.create_account.confirm_password_textbox.fill('ValidPass123!')
    with app.step('Check privacy notice checkbox', action='check', element='create_account.i_have_read_the_privacy_notice_and_under_checkbox'):
        app.pages.create_account.i_have_read_the_privacy_notice_and_under_checkbox.check()
    with app.step("Click 'Create account' button to submit", action='click', element='create_account.create_account_button'):
        app.pages.create_account.create_account_button.click()
    with app.step('Verify form was not submitted (button still visible) indicating validation failure', action='expect_visible', element='create_account.create_account_button'):
        expect(app.pages.create_account.create_account_button).to_be_visible()

