@pytest.mark.tc('TC_AUTH_029')
def test_tc_auth_029_multiple_failed_login_attempts_do_not_lo(app):
    """TC_AUTH_029: Multiple failed login attempts do not lock account

    Scenario: SC_AUTH_001
    Expected: After multiple failed attempts, user can still log in successfully with correct credentials.
    Note: Script navigates to landing page, clicks  Get started  to open login form (get_started page), then performs 4 failed login attempts with wrong password, followed by a successful login with correct credentials. Error message verification is 
    """
    with app.step('Open landing page', action='goto', element=''):
        app.goto('/~/+/')
    with app.step("Click 'Get started' button on landing page", action='click', element='landing.get_started_button'):
        app.pages.landing.get_started_button.click()
    with app.step('Enter valid email', action='fill', element='get_started.email_textbox'):
        app.pages.get_started.email_textbox.fill(app.val('{{env:VALID_USER_EMAIL}}'))
    with app.step('Enter wrong password', action='fill', element='get_started.password_textbox'):
        app.pages.get_started.password_textbox.fill('WrongPassword123!')
    with app.step("Click 'Log in' button (1st failed attempt)", action='click', element='get_started.log_in_button'):
        app.pages.get_started.log_in_button.click()
    with app.step('Enter wrong password again', action='fill', element='get_started.password_textbox'):
        app.pages.get_started.password_textbox.fill('WrongPassword123!')
    with app.step("Click 'Log in' button (2nd failed attempt)", action='click', element='get_started.log_in_button'):
        app.pages.get_started.log_in_button.click()
    with app.step('Enter wrong password again', action='fill', element='get_started.password_textbox'):
        app.pages.get_started.password_textbox.fill('WrongPassword123!')
    with app.step("Click 'Log in' button (3rd failed attempt)", action='click', element='get_started.log_in_button'):
        app.pages.get_started.log_in_button.click()
    with app.step('Enter wrong password again', action='fill', element='get_started.password_textbox'):
        app.pages.get_started.password_textbox.fill('WrongPassword123!')
    with app.step("Click 'Log in' button (4th failed attempt)", action='click', element='get_started.log_in_button'):
        app.pages.get_started.log_in_button.click()
    with app.step('Enter correct password', action='fill', element='get_started.password_textbox'):
        app.pages.get_started.password_textbox.fill(app.val('{{env:VALID_USER_PASSWORD}}'))
    with app.step("Click 'Log in' button with correct credentials", action='click', element='get_started.log_in_button'):
        app.pages.get_started.log_in_button.click()

